/* =========================================================================
   DO NOT EDIT BELOW THIS LINE
   (unless you want to change how the site behaves, not just its content)
   ========================================================================= */

document.addEventListener("DOMContentLoaded", () => {
  renderNames();
  renderHeroDate();
  renderWelcome();
  renderTimeline();
  renderGallery();
  renderLoveCards();
  renderLetter();
  renderFuture();
  renderFinal();

  initBgParticles();
  initScrollButton();
  initTimelineReveal();
  initGalleryLightbox();
  initLoveCards();
  initEnvelope();
  initHeartTap();
  initFinalSurprise();
  initMusicPlayer();
});

/* ---------- Rendering ---------- */

function renderNames() {
  const footer = document.getElementById("footer-names");
  footer.textContent = `Made with ❤️ by ${CONFIG.yourName}, for ${CONFIG.herName}.`;
}

function renderHeroDate() {
  const el = document.getElementById("hero-date");
  const start = new Date(CONFIG.anniversaryDate);
  if (isNaN(start.getTime())) return;
  const now = new Date();
  let months = (now.getFullYear() - start.getFullYear()) * 12 + (now.getMonth() - start.getMonth());
  if (now.getDate() < start.getDate()) months--;
  months = Math.max(months, 0);
  el.textContent = `${CONFIG.herName} & ${CONFIG.yourName} · ${months} months and counting`;
}

function renderWelcome() {
  const el = document.getElementById("welcome-text");
  el.innerHTML = CONFIG.welcomeMessage.map(p => `<p>${escapeHtml(p)}</p>`).join("");
}

function renderTimeline() {
  const el = document.getElementById("timeline-list");
  el.innerHTML = CONFIG.timeline.map(item => `
    <div class="timeline-item">
      <span class="timeline-dot" aria-hidden="true"></span>
      <p class="timeline-month">Month ${item.month} ❤️</p>
      <div class="timeline-card">
        <img src="${item.photo}" alt="Photo from ${escapeHtml(item.date)}" loading="lazy">
        <h3>${escapeHtml(item.title)}</h3>
        <p class="timeline-date">${escapeHtml(item.date)}</p>
        <p class="memory">${escapeHtml(item.memory)}</p>
      </div>
    </div>
  `).join("");
}

function renderGallery() {
  const el = document.getElementById("gallery-grid");
  el.innerHTML = CONFIG.gallery.map((item, i) => `
    <button class="gallery-item" type="button" data-index="${i}" aria-label="Open photo: ${escapeHtml(item.caption)}">
      <img src="${item.photo}" alt="${escapeHtml(item.caption)}" loading="lazy">
      <span class="gallery-caption">${escapeHtml(item.caption)}</span>
    </button>
  `).join("");
}

function renderLoveCards() {
  const el = document.getElementById("love-grid");
  el.innerHTML = CONFIG.thingsILove.map((item, i) => `
    <button class="love-card" type="button" data-index="${i}" aria-label="${escapeHtml(item.front)}">
      <div class="love-card-inner">
        <div class="love-card-face love-card-front">${i + 1}. ${escapeHtml(item.front)}</div>
        <div class="love-card-face love-card-back">${escapeHtml(item.back)}</div>
      </div>
    </button>
  `).join("");
}

function renderLetter() {
  document.getElementById("letter-content").textContent = CONFIG.loveLetter;
}

function renderFuture() {
  document.getElementById("future-text").textContent = CONFIG.futureMessage;
}

function renderFinal() {
  document.getElementById("final-reveal").textContent = CONFIG.finalMessage;
}

function escapeHtml(str) {
  const div = document.createElement("div");
  div.textContent = str;
  return div.innerHTML;
}

/* ---------- Hero scroll button ---------- */

function initScrollButton() {
  document.getElementById("open-heart-btn").addEventListener("click", () => {
    document.getElementById("welcome").scrollIntoView({ behavior: "smooth" });
  });
}

/* ---------- Floating hearts / sparkles background ---------- */

function initBgParticles() {
  const canvas = document.getElementById("bg-canvas");
  const ctx = canvas.getContext("2d");
  let particles = [];
  let width, height;
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function resize() {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
  }
  window.addEventListener("resize", resize);
  resize();

  const count = reduceMotion ? 0 : Math.min(28, Math.floor(width / 45));

  function makeParticle() {
    const isHeart = Math.random() > 0.4;
    return {
      x: Math.random() * width,
      y: height + Math.random() * height,
      size: isHeart ? 6 + Math.random() * 10 : 1.5 + Math.random() * 2,
      speed: 0.25 + Math.random() * 0.5,
      drift: (Math.random() - 0.5) * 0.4,
      isHeart,
      opacity: 0.15 + Math.random() * 0.35
    };
  }

  for (let i = 0; i < count; i++) particles.push(makeParticle());

  function drawHeart(x, y, size, opacity) {
    ctx.save();
    ctx.globalAlpha = opacity;
    ctx.fillStyle = "#E8A6B4";
    ctx.beginPath();
    ctx.moveTo(x, y + size * 0.3);
    ctx.bezierCurveTo(x, y, x - size / 2, y, x - size / 2, y + size * 0.3);
    ctx.bezierCurveTo(x - size / 2, y + size * 0.6, x, y + size * 0.8, x, y + size);
    ctx.bezierCurveTo(x, y + size * 0.8, x + size / 2, y + size * 0.6, x + size / 2, y + size * 0.3);
    ctx.bezierCurveTo(x + size / 2, y, x, y, x, y + size * 0.3);
    ctx.fill();
    ctx.restore();
  }

  function drawSparkle(x, y, size, opacity) {
    ctx.save();
    ctx.globalAlpha = opacity;
    ctx.fillStyle = "#C99A5B";
    ctx.beginPath();
    ctx.arc(x, y, size, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  function tick() {
    ctx.clearRect(0, 0, width, height);
    particles.forEach(p => {
      p.y -= p.speed;
      p.x += p.drift;
      if (p.y < -20) Object.assign(p, makeParticle(), { y: height + 20 });
      if (p.isHeart) drawHeart(p.x, p.y, p.size, p.opacity);
      else drawSparkle(p.x, p.y, p.size, p.opacity);
    });
    requestAnimationFrame(tick);
  }
  if (!reduceMotion) tick();
}

/* ---------- Timeline scroll reveal ---------- */

function initTimelineReveal() {
  const items = document.querySelectorAll(".timeline-item");
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add("in-view");
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.2 });
  items.forEach(item => observer.observe(item));
}

/* ---------- Gallery lightbox ---------- */

function initGalleryLightbox() {
  const lightbox = document.getElementById("lightbox");
  const img = document.getElementById("lightbox-img");
  const caption = document.getElementById("lightbox-caption");
  const closeBtn = document.getElementById("lightbox-close");

  document.getElementById("gallery-grid").addEventListener("click", (e) => {
    const btn = e.target.closest(".gallery-item");
    if (!btn) return;
    const item = CONFIG.gallery[Number(btn.dataset.index)];
    img.src = item.photo;
    img.alt = item.caption;
    caption.textContent = item.caption;
    lightbox.classList.add("open");
    lightbox.setAttribute("aria-hidden", "false");
  });

  function close() {
    lightbox.classList.remove("open");
    lightbox.setAttribute("aria-hidden", "true");
  }
  closeBtn.addEventListener("click", close);
  lightbox.addEventListener("click", (e) => { if (e.target === lightbox) close(); });
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") close(); });
}

/* ---------- 10 things I love cards ---------- */

function initLoveCards() {
  document.getElementById("love-grid").addEventListener("click", (e) => {
    const card = e.target.closest(".love-card");
    if (!card) return;
    card.classList.toggle("open");
  });
}

/* ---------- Envelope + love letter ---------- */

function initEnvelope() {
  const envelope = document.getElementById("envelope");
  const openBtn = document.getElementById("open-letter-btn");
  const closeBtn = document.getElementById("close-letter-btn");
  const paper = document.getElementById("letter-paper");

  openBtn.addEventListener("click", () => {
    envelope.classList.add("open");
    paper.classList.add("visible");
    paper.setAttribute("aria-hidden", "false");
    requestAnimationFrame(() => {
      setTimeout(() => paper.classList.add("show"), 250);
    });
    setTimeout(() => paper.scrollIntoView({ behavior: "smooth", block: "center" }), 500);
  });

  closeBtn.addEventListener("click", () => {
    paper.classList.remove("show");
    envelope.classList.remove("open");
    setTimeout(() => {
      paper.classList.remove("visible");
      paper.setAttribute("aria-hidden", "true");
    }, 400);
  });
}

/* ---------- Interactive heart ---------- */

function initHeartTap() {
  const heart = document.getElementById("big-heart");
  const countEl = document.getElementById("tap-count");
  const msgEl = document.getElementById("tap-message");
  let taps = 0;

  heart.addEventListener("click", (e) => {
    taps++;
    countEl.textContent = `${taps} tap${taps === 1 ? "" : "s"}`;
    msgEl.textContent = CONFIG.heartMessages[Math.floor(Math.random() * CONFIG.heartMessages.length)];

    heart.classList.remove("pulse");
    void heart.offsetWidth; // restart animation
    heart.classList.add("pulse");

    spawnMiniHearts(e.clientX, e.clientY);
  });
}

function spawnMiniHearts(x, y) {
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reduceMotion) return;
  for (let i = 0; i < 6; i++) {
    const el = document.createElement("span");
    el.textContent = "❤";
    el.style.position = "fixed";
    el.style.left = `${x}px`;
    el.style.top = `${y}px`;
    el.style.pointerEvents = "none";
    el.style.fontSize = `${12 + Math.random() * 14}px`;
    el.style.color = "#E8A6B4";
    el.style.zIndex = "70";
    el.style.transition = "transform 1s ease-out, opacity 1s ease-out";
    document.body.appendChild(el);
    const dx = (Math.random() - 0.5) * 160;
    const dy = -80 - Math.random() * 100;
    requestAnimationFrame(() => {
      el.style.transform = `translate(${dx}px, ${dy}px)`;
      el.style.opacity = "0";
    });
    setTimeout(() => el.remove(), 1050);
  }
}

/* ---------- Final surprise + confetti ---------- */

function initFinalSurprise() {
  const btn = document.getElementById("final-btn");
  const reveal = document.getElementById("final-reveal");

  btn.addEventListener("click", () => {
    reveal.classList.add("visible");
    requestAnimationFrame(() => {
      setTimeout(() => reveal.classList.add("show"), 50);
    });
    launchConfetti();
    btn.disabled = true;
    btn.style.opacity = "0.6";
  });
}

function launchConfetti() {
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reduceMotion) return;

  const canvas = document.getElementById("confetti-canvas");
  const ctx = canvas.getContext("2d");
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  const colors = ["#E8A6B4", "#C99A5B", "#7A2E42", "#F7D9D9", "#FFFFFF"];
  const pieces = Array.from({ length: 90 }, () => ({
    x: Math.random() * canvas.width,
    y: -20 - Math.random() * canvas.height * 0.5,
    size: 5 + Math.random() * 6,
    speed: 1.5 + Math.random() * 2.5,
    drift: (Math.random() - 0.5) * 2,
    rotation: Math.random() * 360,
    rotSpeed: (Math.random() - 0.5) * 8,
    color: colors[Math.floor(Math.random() * colors.length)],
    isHeart: Math.random() > 0.5
  }));

  let frame = 0;
  const maxFrames = 260;

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    pieces.forEach(p => {
      p.y += p.speed;
      p.x += p.drift;
      p.rotation += p.rotSpeed;
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate((p.rotation * Math.PI) / 180);
      ctx.fillStyle = p.color;
      if (p.isHeart) {
        ctx.beginPath();
        const s = p.size;
        ctx.moveTo(0, s * 0.3);
        ctx.bezierCurveTo(0, 0, -s / 2, 0, -s / 2, s * 0.3);
        ctx.bezierCurveTo(-s / 2, s * 0.6, 0, s * 0.8, 0, s);
        ctx.bezierCurveTo(0, s * 0.8, s / 2, s * 0.6, s / 2, s * 0.3);
        ctx.bezierCurveTo(s / 2, 0, 0, 0, 0, s * 0.3);
        ctx.fill();
      } else {
        ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size * 0.4);
      }
      ctx.restore();
    });
    frame++;
    if (frame < maxFrames) {
      requestAnimationFrame(draw);
    } else {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
    }
  }
  draw();
}

/* ---------- Music player ---------- */

function initMusicPlayer() {
  const btn = document.getElementById("music-btn");
  const audio = document.getElementById("bg-audio");
  audio.volume = 0.5;

  btn.addEventListener("click", () => {
    if (audio.paused) {
      audio.play().catch(() => {
        // File may be missing until the user adds assets/music/our-song.mp3
      });
      btn.classList.add("playing");
    } else {
      audio.pause();
      btn.classList.remove("playing");
    }
  });
}
